/**
 * route-scorer.mjs — deterministic skill/agent routing for intent-classifier.js.
 *
 * Scores a prompt against ccc-routes.json (generated by scripts/build-routes.js)
 * and renders the short <ccc-route> / <ccc-next> blocks injected into the
 * model's context. Pure functions only: no filesystem writes, no prompt
 * logging. Shared verbatim by the Claude Code and Codex plugins.
 *
 * Scoring (capped at 1.0):
 *   intent pattern (regex)        +0.60 each distinct, at most two
 *   strong trigger (distinctive)  +0.60
 *   curated trigger, multi-word   +0.35
 *   curated trigger, single word  +0.25
 *   description phrase            +0.25
 *   path/file mention             +0.20
 *   negative pattern              route removed
 * Ties sort by route priority (route-hints.json, default 0), then skill first.
 * Tiers: high  = intent pattern hit, top >= 0.8, 0.25 lead over runner-up
 *        medium = top >= 0.55 (one generic keyword alone never fires)
 *        low   = silent
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const HIGH_THRESHOLD = 0.8;
export const HIGH_MARGIN = 0.25;
export const MEDIUM_THRESHOLD = 0.55;
export const MAX_CONTEXT_CHARS = 600;
const MIN_LISTED_SCORE = 0.3;
// Two next steps + "Done for now" + this = AskUserQuestion's 4-option cap.
export const MUTE_NEXT_LABEL = 'Stop suggesting next steps';
const ANALYZED_CHARS = 600;

const WEIGHTS = { pattern: 0.6, strong: 0.6, phrase: 0.35, word: 0.25, desc: 0.25, path: 0.2 };

let cachedRoutes = null;

export function loadRoutes(file = join(dirname(fileURLToPath(import.meta.url)), 'ccc-routes.json')) {
  if (cachedRoutes && cachedRoutes.file === file) return cachedRoutes.routes;
  const routes = JSON.parse(readFileSync(file, 'utf8')).routes.map(compileRoute);
  cachedRoutes = { file, routes };
  return routes;
}

function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Whole-word phrase: "post" must not match "postgres", "review" must not
// match "preview". The last word may take a plural s/es.
function phraseRegex(phrase) {
  const body = phrase.split(/\s+/).map(escapeRegex).join('[\\s-]+');
  const plural = /[a-z]$/i.test(phrase) ? '(?:s|es)?' : '';
  return new RegExp(`(?<![\\w-])${body}${plural}(?![\\w-])`, 'i');
}

function pathRegex(p) {
  // ".go" → a file name ending in .go; "Dockerfile" → that word.
  if (p.startsWith('.') && !p.includes('/')) return new RegExp(`\\w${escapeRegex(p)}(?![\\w.])`, 'i');
  return new RegExp(`(?<![\\w-])${escapeRegex(p)}(?![\\w-])`, 'i');
}

function compileRoute(route) {
  return {
    ...route,
    _triggers: [
      ...route.strong.map((t) => ({ re: phraseRegex(t), weight: WEIGHTS.strong })),
      ...route.triggers.map((t) => ({ re: phraseRegex(t), weight: /\s/.test(t) ? WEIGHTS.phrase : WEIGHTS.word })),
    ],
    _desc: route.descTriggers.map((t) => phraseRegex(t)),
    _patterns: route.patterns.map((p) => new RegExp(p, 'i')),
    _negatives: route.negatives.map((p) => new RegExp(p, 'i')),
    _paths: route.paths.map(pathRegex),
  };
}

/**
 * Why this prompt must not be routed, or null. Explicit commands and
 * machine-generated turns (task notifications, loop ticks, sub-agent
 * reports, hook-injected tags) are never routed.
 */
export function skipReason(rawPrompt, payload = {}) {
  const prompt = String(rawPrompt || '').trim();
  if (!prompt) return 'empty';
  if (/^[/$][\w:-]+/.test(prompt)) return 'explicit-command';
  if (/^<[\w-]+[\s>]/.test(prompt)) return 'non-human';
  if (/^\[SYSTEM NOTIFICATION/i.test(prompt)) return 'non-human';
  if (/<<autonomous-loop/.test(prompt)) return 'non-human';
  if (payload.agent_id || payload.agent_type) return 'subagent';
  return null;
}

// A double-quoted span on one line ("...", or curly quotes) names something
// the user is quoting, not the job they are asking for.
const DOUBLE_QUOTED = /"[^"\n]*"|\u201c[^\u201d\n]*\u201d/g;

// Already-stripped text to one lowercased line: quoted spans and URLs out,
// whitespace collapsed, cut at maxChars.
function flatten(text, maxChars) {
  return String(text || '')
    .replace(DOUBLE_QUOTED, ' ')
    // Typographic apostrophes ("Don\u2019t") read as ASCII so negations match.
    .replace(/[\u2018\u2019\u02bc]/g, "'")
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxChars)
    .toLowerCase();
}

/**
 * Lowercased routing text, first 600 chars (or maxChars): code fences and
 * spans, indented code, blockquotes, pasted blocks, URLs and double-quoted
 * spans are removed by the same rules a worker task uses (blankQuoted).
 */
export function normalizePrompt(prompt, maxChars = ANALYZED_CHARS) {
  return flatten(blankQuoted(prompt), maxChars);
}

// What the user says not to do is not a request to do it: "don't deploy",
// "skip the review", "no need to write tests", "you should not write unit
// tests here", "let's not deploy", "it is not necessary to add tests". A
// directive negator in a command position (start of a sentence or clause,
// after a joining word, or after a spaced dash) blanks the rest of its clause,
// up to the sentence end, a spaced dash, a contrast marker ("but",
// "instead", "just", "only", "rather", "then") or a new imperative clause. A subject-led negation ("you must
// not", "we shouldn't", "let's not", "it is not necessary to") counts at any
// position. A double negation ("don't skip the tests", "never forget to") is
// a request and stays. Descriptions of a problem ("the tests don't work",
// "login is not working", "it doesn't build") are not directives and stay.
// Applied in scoreRoutes only: looksLikeWork and fleet intents still see the
// whole request.
// A new imperative clause after a comma ("skip deployment, then write
// tests", "don't deploy, write unit tests for my code") also ends the
// negation; a bare list ("don't deploy, build or test") does not, and
// neither does a list of prohibitions closed by a comma, "or"/"nor" and any
// verb ("do not write docs, write unit tests, or publish a release"); a
// preposition or adverb after ", or" ("..., or in JavaScript if you prefer")
// continues the new clause. An "or" without that comma belongs to the new
// clause ("skip deployment, write unit tests for my code or run integration
// tests" asks for tests).
const CLAUSE_VERB = String.raw`(?:write|add|run|review|fix|debug|build|create|make|test|update|refactor|implement|check|explain|plan|ship|document|audit|deploy|generate|set|draft|scan|summarize|optimize|design)`;
// Closed-class words that cannot start a verb phrase. ", or in JavaScript", ", or with jest", ", or if you
// prefer" continue the new clause instead of closing a prohibition list (Codex #302 delta4); any other word
// after ", or"/", nor" is read as a verb, since verbs are an open class (Codex #302 delta3 NM3).
const NOT_A_VERB = String.raw`(?:in|into|on|onto|at|with|without|within|by|for|from|to|of|as|via|using|per|over|under|after|before|during|until|unless|than|like|if|when|whenever|where|wherever|whether|whichever|whatever|while|otherwise|else|alternatively|preferably|ideally|possibly|perhaps|maybe|even|also|just|only|so|not|both|either|neither|the|a|an|my|our|your|its|their|this|that|these|those|any|some|it|you|we|they|me|us|them|anything|something)`;
const LIST_TAIL = String.raw`(?![^.!?;]*?,\s*(?:or|nor)\s+(?!${NOT_A_VERB}\b)\w)`;
const NEGATION_END = String.raw`(?=[.!?;]|\s[-\u2013\u2014]+\s|\b(?:but|instead|just|only|rather|then)\b|,\s*now\b|,\s*${CLAUSE_VERB}\s+(?:the|a|an|my|our|your|this|that|these|those|some|unit|it|me|up|all)\b${LIST_TAIL}|$)`;
const COMMAND_POSITION = String.raw`(?:^|(?:[.!?;:,(]|\s[-\u2013\u2014]+)\s*|\b(?:and|but|so|then|please|pls|also|or)\s+)`;
// "don't skip", "never forget to", "you shouldn't avoid": two negations make a request.
const NOT_DOUBLE = String.raw`(?!\s+(?:skip|skipping|avoid|avoiding|forget|omit|neglect|ignore|stop)\b)`;
const DIRECTIVE = String.raw`(?:do not|don'?t|never|skip|avoid)\b(?!\s+(?:know|understand|see|get|think|remember|care|mind)\b)${NOT_DOUBLE}`;
const SUBJECT_NEGATION = String.raw`(?:` +
  String.raw`\b(?:you|we|they|i|one)\s+(?:(?:should|must|shall|ought)(?:\s+not|n'?t)(?:\s+to)?|need\s+not|needn'?t|(?:do\s+not|don'?t)\s+(?:need|have)\s+to)(?!\s+(?:have|be)\b)` +
  String.raw`|\blet(?:'?s|\s+us)\s+not` +
  String.raw`|\b(?:it|this|that)(?:\s+is\s+not|\s+isn'?t|'s\s+not)\s+(?:necessary|needed|required)(?:\s+to)?` +
  String.raw`)\b${NOT_DOUBLE}`;
const NEGATED = new RegExp(
  `(${COMMAND_POSITION}|\\b(?:i|we)\\s+(?=(?:do not|don'?t) (?:want|need)\\b))(${DIRECTIVE}[^.!?;]*?)${NEGATION_END}` +
    `|()((?:\\b(?:no need to|without \\w+ing)\\b|${SUBJECT_NEGATION})[^.!?;]*?)${NEGATION_END}`,
  'g'
);

/** Blank negated directives (see NEGATED) in normalized text; length is kept. */
export function stripNegated(text) {
  return String(text || '').replace(NEGATED, (m, lead, neg, lead2, neg2) => {
    const body = neg !== undefined ? neg : neg2;
    return m.slice(0, m.length - body.length) + ' '.repeat(body.length);
  });
}

/** Score every route; returns candidates sorted by score (desc), score > 0 only. */
export function scoreRoutes(prompt, routes = loadRoutes(), opts = {}) {
  const text = stripNegated(opts.normalized ? String(prompt || '') : normalizePrompt(prompt));
  if (!text.trim()) return [];
  const candidates = [];
  for (const route of routes) {
    if (route._negatives.some((re) => re.test(text))) continue;
    if (route.requirePath && !route._paths.some((re) => re.test(text))) continue;
    let score = 0;
    let patternHits = 0;
    for (const re of route._patterns) {
      if (patternHits < 2 && re.test(text)) {
        score += WEIGHTS.pattern;
        patternHits += 1;
      }
    }
    for (const t of route._triggers) if (t.re.test(text)) score += t.weight;
    for (const re of route._desc) if (re.test(text)) score += WEIGHTS.desc;
    for (const re of route._paths) if (re.test(text)) score += WEIGHTS.path;
    if (score > 0) candidates.push({ route, score: Math.min(1, Math.round(score * 100) / 100), patternHits });
  }
  // Ties: higher route-hints priority first, then skills before agents (a
  // skill is the cheaper, in-thread path).
  const kindRank = (c) => (c.route.kind === 'skill' ? 0 : 1);
  candidates.sort((a, b) => b.score - a.score || (b.route.priority || 0) - (a.route.priority || 0) || kindRank(a) - kindRank(b));
  return candidates;
}

// A worker's task often opens with a long shared preamble (repo rules,
// worktree notes) and states the job further down, so a task is scored in
// pieces and each route keeps its best piece: the first line (usually the
// description), every line that names the task, and 600-character windows
// over the first TASK_CHARS characters.
export const TASK_CHARS = 4000;
const TASK_LINE = /^\s*(?:[#*-]+\s*)?(?:\*\*)?(?:task|goal|objective|your (?:task|job|slice)|slice \d+|deliverable|what to do|todo|ticket|issue|bug|fix|implement|build)\b/i;
const WINDOW_STEP = 450;

// Code fences (``` or ~~~, closed only by the same character at least as
// long), blockquotes with their lazy continuation lines, inline code, URLs
// and pasted blocks are quoted material, not
// the job: blanked out of the whole task (line breaks kept) before any line
// or window is read, and the result is cut at TASK_CHARS.
// A heading, list item or thematic break: it ends a blockquote's lazy continuation.
const BLOCK_START = /^ {0,3}(?:#{1,6}(?:\s|$)|[-*+]\s|\d{1,9}[.)]\s|(?:[-*_]\s*){3,}$)/;
// Index of the next run of exactly n backticks at or after from, or -1. A code span of N backticks closes
// only on a run of exactly N.
function findRun(line, from, n) {
  const re = /`+/g;
  re.lastIndex = from;
  for (let r = re.exec(line); r; r = re.exec(line)) if (r[0].length === n) return r.index;
  return -1;
}

// stripQuoted without the TASK_CHARS cut: normalizePrompt cuts after
// collapsing whitespace, so a long paste cannot push the request out.
function blankQuoted(text) {
  const blank = (m) => m.replace(/[^\n]/g, ' ');
  const lines = String(text || '').replace(/<pasted_content[\s\S]*?(<\/pasted_content[^>]*>|$)/g, blank).split('\n');
  let fence = null; // { ch, len } of the open fence
  let quote = false; // inside a blockquote paragraph (lazy continuation lines count)
  let code = false; // inside an indented code block
  let prevBlank = true; // an indented code block starts after a blank line (or at the top)
  let span = 0; // backtick count of a code span still open from an earlier line of this paragraph
  // Blank code spans of any backtick length, including one that runs on from (or into) another line.
  // Does a run of exactly n backticks close the span later in this paragraph? If not, the opening run is
  // literal text (CommonMark), not the start of a code span.
  const closesLater = (idx, n) => {
    for (let k = idx + 1; k < lines.length && lines[k].trim(); k++) if (findRun(lines[k], 0, n) >= 0) return true;
    return false;
  };
  let lineNo = -1;
  const inline = (line) => {
    let out = '';
    let i = 0;
    if (span) {
      const close = findRun(line, 0, span);
      if (close < 0) return blank(line);
      out += blank(line.slice(0, close + span));
      i = close + span;
      span = 0;
    }
    for (;;) {
      const m = /`+/g;
      m.lastIndex = i;
      const r = m.exec(line);
      if (!r) return out + line.slice(i);
      const len = r[0].length;
      const close = findRun(line, r.index + len, len);
      if (close < 0) {
        if (!closesLater(lineNo, len)) { out += line.slice(i, r.index + len); i = r.index + len; continue; }
        span = len;
        return out + line.slice(i, r.index) + blank(line.slice(r.index));
      }
      out += line.slice(i, r.index) + blank(line.slice(r.index, close + len));
      i = close + len;
    }
  };
  const out = lines.map((line, idx) => {
    lineNo = idx;
    const wasBlank = prevBlank;
    prevBlank = !line.trim();
    if (fence) {
      const close = line.match(/^ {0,3}(`{3,}|~{3,})\s*$/);
      if (close && close[1][0] === fence.ch && close[1].length >= fence.len) fence = null;
      return '';
    }
    if (!line.trim()) { quote = false; span = 0; return line; }
    // Four spaces or a tab after a blank line (or continuing such a block) is an indented code block.
    if (/^(?: {4}|\t)/.test(line) && (code || (wasBlank && !quote))) { code = true; return ''; }
    code = false;
    const open = line.match(/^ {0,3}(`{3,}|~{3,})/);
    if (open) { fence = { ch: open[1][0], len: open[1].length }; quote = false; return ''; }
    if (/^ {0,3}>/.test(line)) { quote = true; return ''; }
    // A lazy quote line is paragraph text; a heading, list item or rule starts a new block.
    if (quote && !BLOCK_START.test(line)) return '';
    quote = false;
    if (span && BLOCK_START.test(line)) span = 0;
    return inline(line).replace(/https?:\/\/\S+/g, blank);
  });
  return out.join('\n');
}

function stripQuoted(text) {
  return blankQuoted(text).slice(0, TASK_CHARS);
}

function taskSegments(task) {
  const raw = stripQuoted(task);
  const lines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const segments = [];
  if (lines.length) segments.push(lines[0]);
  lines.forEach((line, i) => {
    if (i > 0 && TASK_LINE.test(line)) segments.push(lines.slice(i, i + 3).join(' '));
  });
  // raw is already stripped; stripping again could misread blanked spans as indented code.
  const flat = flatten(raw, TASK_CHARS);
  for (let start = 0; start < flat.length; start += WINDOW_STEP) {
    segments.push(flat.slice(start, start + ANALYZED_CHARS));
    if (start + ANALYZED_CHARS >= flat.length) break;
  }
  return segments;
}

/**
 * Score a worker task (fleet job, subagent prompt): like scoreRoutes, but the
 * whole task up to TASK_CHARS is read, in pieces, and each route keeps the
 * score of its best piece. Same sort order as scoreRoutes.
 */
export function scoreTask(task, routes = loadRoutes()) {
  const best = new Map();
  for (const segment of taskSegments(task)) {
    for (const c of scoreRoutes(segment, routes)) {
      const prev = best.get(c.route.id);
      if (!prev || c.score > prev.score || (c.score === prev.score && c.patternHits > prev.patternHits)) best.set(c.route.id, c);
    }
  }
  const kindRank = (c) => (c.route.kind === 'skill' ? 0 : 1);
  return [...best.values()].sort((a, b) => b.score - a.score || (b.route.priority || 0) - (a.route.priority || 0) || kindRank(a) - kindRank(b));
}

const ROUTE_MODES = ['off', 'suggest', 'auto', 'always'];

// always: below the menu threshold, a prompt that still touches a skill gets a one-line hint.
export const HINT_THRESHOLD = 0.3;

function validMode(value) {
  const mode = String(value || '').trim().toLowerCase();
  return ROUTE_MODES.includes(mode) ? mode : null;
}

/**
 * Route mode: off | suggest | auto | always. A valid CCC_ROUTE_MODE wins, then the
 * lane's saved `routeMode` preference (config.json, set by /ccc-settings),
 * then auto. Unknown values are ignored. `always` is the power-user mode:
 * a clear match runs as in auto, a likely match runs its top skill instead of
 * offering a menu, and a weak match gets a one-line hint (tier "hint").
 */
export function routeMode(env = process.env, saved = null) {
  return validMode(env.CCC_ROUTE_MODE) || validMode(saved) || 'auto';
}

export function tierFor(candidates, mode = 'auto') {
  if (mode === 'off' || !candidates.length) return 'low';
  const [top, second] = candidates;
  if (top.score < MEDIUM_THRESHOLD) return mode === 'always' && top.score >= HINT_THRESHOLD ? 'hint' : 'low';
  const clearWinner = top.score >= HIGH_THRESHOLD && top.score - (second ? second.score : 0) >= HIGH_MARGIN;
  // Topic scores alone cannot authorize an auto-run. Curated patterns must
  // express a request to do this skill's job, not merely name its subject.
  // Manual (disable-model-invocation) skills and agents never auto-run.
  // No mode auto-runs a side-effect skill, even on a clear match.
  if (isSideEffect(top.route)) return 'medium';
  if (clearWinner && top.patternHits > 0 && (mode === 'auto' || mode === 'always') && top.route.kind === 'skill' && !top.route.manual) return 'high';
  return 'medium';
}

/** claude-code | codex. */
export function detectHost(env = process.env, moduleUrl = import.meta.url) {
  if (env.CCC_SOURCE_APP === 'codex' || env.CCC_SOURCE_APP === 'claude-code') return env.CCC_SOURCE_APP;
  if (env.PLUGIN_ROOT || /cowork-plugin-codex|\/\.codex\//.test(moduleUrl)) return 'codex';
  return 'claude-code';
}

// One headless rule for every hook that could emit a picker.
export { isHeadless } from './headless.mjs';

// A request to do work (not a quick question): the always-mode check line
// is added only for these when no route matched.
const WORK_VERB = /\b(fix|debug|add|build|implement|create|write|refactor|migrate|update|set ?up|make|review|test|deploy|optimi[sz]e|clean ?up|remove|delete|rename|investigate|check|improve|design|document|split|bump|upgrade|port|convert|integrate|wire|ship|audit|speed up|shrink|harden|scaffold|draft|plan|research|analy[sz]e|profile|benchmark|validate|polish|tidy|restyle|redesign|rewrite|log|scan)\b/;
const WORK_SIGNAL = /\b(bug|error|broken|failing|fails|failed|crash\w*|slow|leak|regression|exception|timeout|timing out|500|404|blank|not working|doesn'?t work|isn'?t working|wrong)\b/;

/** Does this prompt ask for work, as opposed to a quick question or chat? */
export function looksLikeWork(prompt) {
  const text = normalizePrompt(prompt);
  if (text.split(' ').filter(Boolean).length < 4) return false;
  return WORK_VERB.test(text) || WORK_SIGNAL.test(text);
}

function invokeText(route, host) {
  if (route.kind === 'agent') return `${route.invoke} agent`;
  return host === 'codex' ? `$${route.id}` : route.invoke;
}

function optionText(route, host) {
  const manual = route.manual ? ' (user types it)' : '';
  const fresh = route.kind === 'agent' ? ' (fresh context)' : '';
  return `${invokeText(route, host)}: ${route.label}${manual}${fresh}`;
}

// Option counts include the trailing "Just answer": AskUserQuestion takes up
// to 4 options, Codex request_user_input 2-3 (its client adds "Other").
// CCC_ROUTE_MENU=list swaps the native picker for a numbered list; the host
// (and so skill naming) is unchanged.
function useList(env = process.env) {
  return String(env.CCC_ROUTE_MENU || '').toLowerCase() === 'list';
}

function menuInstruction(host, count) {
  if (useList()) return 'Show a numbered list, best first, plus "Just answer".';
  if (host === 'codex') {
    return `Call request_user_input once: 1 question, ${count + 1} options, best first with "(Recommended)", last "Just answer".`;
  }
  return `Call AskUserQuestion once: 1 question, ${count + 1} options, best first marked 🟢, last "Just answer".`;
}

function clamp(text) {
  return text.length <= MAX_CONTEXT_CHARS ? text : `${text.slice(0, MAX_CONTEXT_CHARS - 14)}…</ccc-route>`;
}

// Skills that act outside the conversation: deploys, pushes, publishing,
// tracker, fleet or memory writes, settings, long loops. Each skill declares
// this as `sideEffect` in commander/core/route-hints.json (the build fails
// when one does not), and build-routes copies it into ccc-routes.json. No
// route mode tells the model to run these on its own; they are only offered
// as a menu for the user to pick.
// Read lazily: importing this module must never read the registry, so a
// missing or damaged ccc-routes.json cannot break hooks that only import it.
let sideEffectIds = null;
export function sideEffectSkills() {
  if (!sideEffectIds) sideEffectIds = new Set(loadRoutes().filter((r) => r.sideEffect).map((r) => r.id));
  return sideEffectIds;
}

/**
 * Does this route act outside the conversation? Its own flag, or the bundled
 * registry's (older registries lack the flag); when neither says no, it is.
 */
export function isSideEffect(route) {
  if (!route) return false;
  if (route.sideEffect === true) return true;
  try { return sideEffectSkills().has(route.id); } catch { return route.sideEffect !== false; }
}

// Hidden (disable-model-invocation) skills that only read and advise, so
// `always` mode may follow them by reading their SKILL.md. An allowlist: a
// hidden skill is never followed unless it is named here.
export const FOLLOWABLE_HIDDEN_SKILLS = new Set(['ccc-brainstorm', 'ccc-code-review', 'ccc-changelog']);

const PLUGIN_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** A hidden skill the model may follow by reading its file (always mode only). */
export function followable(route) {
  return route.kind === 'skill' && !!route.manual && FOLLOWABLE_HIDDEN_SKILLS.has(route.id) && !isSideEffect(route);
}

// What a worker given a CCC skill may and may not do with it. The same text
// is in ccc-fleet-run.workflow.js and lib/route-task.mjs (a test keeps them equal).
export const WORKER_RULES = "Use the skill's method inside this task only: do not start other agents or workflows (do that step yourself or skip it); where the skill asks how to do the task, pick the option that stays inside the task as written; where it asks for approval (code edits during an audit, installing packages, creating a project, deploy, push, publish, tracker or settings changes), do not proceed and report the decision in your result instead. An audit reports findings and changes nothing unless the task says to fix them.";

/**
 * May a fleet or workflow worker load this skill on its own? Only skills
 * marked `worker` in route-hints.json: visible, no side effect, and a main
 * path that stays in one thread (no further agents, no question it needs
 * answered). Older registries without the flag hand workers nothing.
 */
export function workerEligible(route) {
  return !!route && route.kind === 'skill' && route.worker === true && !route.manual && !isSideEffect(route);
}

/** May `always` mode tell the model to run this route without asking? */
export function autoFollowable(route) {
  if (route.kind !== 'skill' || isSideEffect(route)) return false;
  return !route.manual || followable(route);
}

function skillCall(route, host) {
  if (route.manual) return `read ${join(PLUGIN_ROOT, 'skills', route.id, 'SKILL.md')} (hidden from the Skill tool)`;
  return host === 'codex' ? `use the ${route.id} skill` : `invoke Skill commander:${route.id}`;
}

/** The <ccc-route> block for the model, or null for the low tier. */
export function renderRouteContext(candidates, tier, host, mode = 'auto', opts = {}) {
  if (tier === 'low' || !candidates.length) return null;
  // Weak tail candidates only add menu noise.
  const top3 = candidates.slice(0, 3).filter((c, i) => i === 0 || c.score >= MIN_LISTED_SCORE);
  const list = top3.map((c) => `${invokeText(c.route, host)} ${c.score.toFixed(2)}`).join(' | ');
  let body;
  if (opts.headless && tier !== 'high') {
    // Nobody can answer a picker: name the best usable skill instead. Side-
    // effect, hidden-only and agent routes are dropped, never offered.
    const usable = top3.filter((c) => autoFollowable(c.route));
    if (!usable.length) return null;
    const [top, ...rest] = usable;
    const alts = rest.map((c) => invokeText(c.route, host)).join(', ');
    // suggest mode stays advisory: name the skill, never run it.
    body = mode === 'suggest'
      ? `Headless, no menu. A CCC skill may fit: ${invokeText(top.route, host)} (${top.route.label})${alts ? `; also ${alts}` : ''}. Mention it in one line; do not run it unless the task asks.`
      : `Headless, no menu. If it fits the task, ${skillCall(top.route, host)} first and follow it (${top.route.label})${alts ? `; else consider ${alts}` : ''}. Otherwise just do the task.`;
  } else if (tier === 'hint') {
    const usable = top3.filter((c) => autoFollowable(c.route));
    if (!usable.length) return null;
    const opts = usable.map((c) => optionText(c.route, host)).join('; ');
    body = `CCC skills that may help: ${opts}. If one fits the task, load it before you start; otherwise just answer.`;
  } else if (tier !== 'high' && mode === 'always' && autoFollowable(top3[0].route)) {
    const top = top3[0].route;
    const alts = top3.slice(1).map((c) => invokeText(c.route, host)).join(', ');
    body = `Likely match: ${skillCall(top, host)} now and follow it (${top.label}). Say so in one line, unless it plainly does not fit${alts ? `; then consider ${alts}` : ''}. Skip skills for a quick factual answer.`;
  } else if (tier === 'high') {
    const top = top3[0].route;
    const how = skillCall(top, host);
    body = `Clear match: ${how} now (${top.label}). Say so in one line first. Skip it if the user only wants a quick answer.`;
  } else if (top3[0].route.manual) {
    // Hidden (disable-model-invocation) skill: the host blocks Skill calls to
    // it, so offer it with the alternatives instead of invoking it (CC-2112).
    // Kept short: paid on every matching prompt (one option ~65 tokens).
    const shown = top3.slice(0, host === 'codex' ? 2 : 3);
    const opts = shown.map((c) => `${invokeText(c.route, host)}: ${c.route.label}${c.route.manual ? '*' : ''}`).join('; ');
    const ask = host === 'claude-code' && !useList() ? 'Offer via AskUserQuestion once, 🟢 first, last "Just answer":' : `${menuInstruction(host, shown.length)} Options:`;
    body = `Hidden skill. ${ask} ${opts}. *User types it; never invoke it.`;
  } else {
    const shown = top3.slice(0, host === 'codex' ? 2 : 3);
    const opts = shown.map((c) => optionText(c.route, host)).join('; ');
    body = `Possible fit. ${menuInstruction(host, shown.length)} Options: ${opts}. Run the pick; manual skills need the user to type them; agents spawn with fresh context.`;
  }
  return clamp(`<ccc-route tier="${tier}" candidates="${list}">\n${body}\n</ccc-route>`);
}

/**
 * always mode, nothing matched, and the prompt asks for work: one short line
 * asking the model to check its own skill list before starting. Keyword
 * routing cannot cover every phrasing; the model can.
 */
export function renderCheckContext(host) {
  const skills = host === 'codex' ? '$ccc-* skill' : 'commander:ccc-* skill';
  return `<ccc-route tier="check">\nNo CCC skill matched by keyword. Before substantial work, check your skill list for a ${skills} that fits (debugging, tests, review, plan, design, SaaS, DevOps, data, security) and load it first; never auto-run deploy, push, publish or tracker skills. For a quick answer, just answer.\n</ccc-route>`;
}

/** The <ccc-next> block offered after a skill finished, or null. */
export function renderNextContext(fromRoute, nextRoutes, host) {
  if (!fromRoute || !nextRoutes.length) return null;
  const opts = nextRoutes.slice(0, 2).map((r) => optionText(r, host)).join('; ');
  const extra = host === 'codex' ? ' plus "Done for now"' : ' plus "Done for now" and "' + MUTE_NEXT_LABEL + '"';
  const ask = useList()
    ? 'Show a short numbered list.'
    : host === 'codex'
      ? 'Call request_user_input once (1 question, max 3 options, first with "(Recommended)").'
      : 'Call AskUserQuestion once (1 question, max 4 options, first marked 🟢).';
  const text = `<ccc-next after="${invokeText(fromRoute, host)}">\n${invokeText(fromRoute, host)} finished. Offer what's next. ${ask} Options: ${opts}${extra}. Run the pick; otherwise stop.\n</ccc-next>`;
  return text.length <= MAX_CONTEXT_CHARS ? text : `${text.slice(0, MAX_CONTEXT_CHARS - 13)}…</ccc-next>`;
}


/**
 * The <ccc-skills> block for a subagent's task, so fleet and workflow workers
 * use the right skills too. Same gates as the parent router: only a high-tier
 * match (score, margin and an intent pattern) is a directive; otherwise the
 * matches are listed as options (from MEDIUM_THRESHOLD in auto mode, from
 * HINT_THRESHOLD in always mode). Side-effect skills, hidden skills (some
 * fan out further agents) and agents are never listed. Null when
 * nothing qualifies. When `forTask` is given (the task was matched to the
 * worker from a queue, not read from its own payload), the block names that
 * task and tells the worker to ignore it if the task is not its own, so a
 * mis-assigned or stale entry is harmless.
 */
/**
 * A worker whose task matched no route, or whose task text never reached
 * the router (a Workflow script's agent makes no Agent tool call): a short
 * pre-run check so it still evaluates CCC skills before starting.
 */
export function renderSubagentCheck(host, queued = false) {
  let ids = [];
  try { ids = loadRoutes().filter(workerEligible).map((r) => (host === 'codex' ? `$${r.id}` : `commander:${r.id}`)); } catch {}
  const guard = queued ? QUEUED_GUARD : '';
  const pick = ids.length
    ? `if one of ${ids.join(', ')} fits your task, load it; load no other CCC skill from here. ${WORKER_RULES}`
    : 'work without a CCC skill.';
  return `<ccc-skills for="subagent">\n${guard}Pre-run check: if your prompt starts with a "CCC pre-run" line, follow that and ignore this block. Otherwise ${pick} If none fits, just start.\n</ccc-skills>`;
}

// A queued task is matched to a worker by agent type and spawn order, not
// by its text (no task text is stored), so the worker is told to check fit.
const QUEUED_GUARD = 'This hint was matched to you by spawn order; if it does not fit your task, ignore this block. ';
const SUBAGENT_CONTEXT_CHARS = 1100;

export function renderSubagentContext(candidates, host, mode = 'auto', queued = false) {
  const floor = mode === 'always' ? HINT_THRESHOLD : MEDIUM_THRESHOLD;
  const usable = candidates
    .filter((c) => c.score >= floor && workerEligible(c.route))
    .slice(0, 3);
  if (!usable.length) return null;
  const [top] = usable;
  const opts = usable.map((c) => `${invokeText(c.route, host)}: ${c.route.label}`).join('; ');
  const directive = candidates[0] === top && tierFor(candidates, mode) === 'high';
  const lead = directive
    ? `Before starting, ${skillCall(top.route, host)} and follow it for this task: ${top.route.label}.`
    : 'If one of these fits your task, load it before you start.';
  // The guard comes first so the length cap can never cut it off.
  const guard = queued ? QUEUED_GUARD : '';
  const text = `<ccc-skills for="subagent">\n${guard}${lead} Matching CCC skills: ${opts}. ${WORKER_RULES}\n</ccc-skills>`;
  return text.length <= SUBAGENT_CONTEXT_CHARS ? text : `${text.slice(0, SUBAGENT_CONTEXT_CHARS - 15)}…</ccc-skills>`;
}
